// Package printstage stores print-ready PDFs generated by the WebView.
//
// The frontend renders annotations into a copy of the original PDF and POSTs
// the bytes to the asset server. Go keeps the file in a private cache
// directory until it is exported or handed to the system print path.
package printstage

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

const (
	// Files left behind by a system viewer are swept after this long.
	sweepAge = 24 * time.Hour
	// Pending tokens stop resolving after this long; the file may still be
	// open in an external reader and is removed by the startup sweep.
	tokenTTL = 30 * time.Minute
)

// Job describes one staged PDF.
type Job struct {
	ID                 string
	Path               string
	DocPath            string
	DocName            string
	IncludeAnnotations bool
	Created            time.Time
}

type Store struct {
	mu   sync.Mutex
	dir  string
	jobs map[string]Job
	ttl  time.Duration
}

// New creates the cache directory and sweeps stale files from previous runs.
func New(dir string) (*Store, error) {
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, err
	}
	s := &Store{dir: dir, jobs: make(map[string]Job), ttl: tokenTTL}
	s.Sweep()
	return s, nil
}

func (s *Store) Dir() string {
	return s.dir
}

// Stage copies a generated PDF into the cache and returns a one-time id.
func (s *Store) Stage(r io.Reader, docPath, docName string, includeAnnotations bool) (Job, error) {
	if s == nil {
		return Job{}, fmt.Errorf("打印暂存不可用")
	}
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return Job{}, err
	}
	id := hex.EncodeToString(buf)
	dir := filepath.Join(s.dir, id)
	if err := os.Mkdir(dir, 0o700); err != nil {
		return Job{}, err
	}
	path := filepath.Join(dir, stagedFileName(docName, includeAnnotations))
	fail := func(err error) (Job, error) {
		os.RemoveAll(dir)
		return Job{}, err
	}

	f, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_RDWR, 0o600)
	if err != nil {
		return fail(err)
	}
	if _, err := io.Copy(f, r); err != nil {
		f.Close()
		return fail(err)
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return fail(err)
	}
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		f.Close()
		return fail(err)
	}
	head := make([]byte, 5)
	if _, err := io.ReadFull(f, head); err != nil || string(head) != "%PDF-" {
		f.Close()
		return fail(fmt.Errorf("暂存内容不是 PDF"))
	}
	if err := f.Close(); err != nil {
		return fail(err)
	}

	job := Job{
		ID:                 id,
		Path:               path,
		DocPath:            docPath,
		DocName:            docName,
		IncludeAnnotations: includeAnnotations,
		Created:            time.Now(),
	}
	s.mu.Lock()
	s.jobs[id] = job
	s.mu.Unlock()
	return job, nil
}

func stagedFileName(docName string, includeAnnotations bool) string {
	base := filepath.Base(strings.TrimSpace(docName))
	base = strings.TrimSuffix(base, filepath.Ext(base))
	base = strings.Map(func(r rune) rune {
		switch r {
		case '/', '\\', ':', '*', '?', '"', '<', '>', '|':
			return '_'
		}
		if r < 0x20 {
			return '_'
		}
		return r
	}, base)
	if base == "" || base == "." {
		base = "文档"
	}
	suffix := "副本"
	if includeAnnotations {
		suffix = "标注"
	}
	name := fmt.Sprintf("%s (%s).pdf", base, suffix)
	if len([]rune(name)) > 120 {
		name = string([]rune(name)[:120]) + ".pdf"
	}
	return name
}

func removeJobFiles(job Job) {
	_ = os.Remove(job.Path)
	_ = os.Remove(filepath.Dir(job.Path))
}

// Get resolves an id while it is still fresh.
func (s *Store) Get(id string) (Job, bool) {
	if s == nil {
		return Job{}, false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	job, ok := s.jobs[id]
	if !ok {
		return Job{}, false
	}
	if time.Since(job.Created) > s.ttl {
		delete(s.jobs, id)
		removeJobFiles(job)
		return Job{}, false
	}
	return job, true
}

// Discard removes a staged file (used when the user cancels).
func (s *Store) Discard(id string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	job, ok := s.jobs[id]
	delete(s.jobs, id)
	s.mu.Unlock()
	if ok {
		removeJobFiles(job)
	}
}

// SaveTo atomically copies a staged PDF to the user's chosen path.
func (s *Store) SaveTo(id, target string) error {
	job, ok := s.Get(id)
	if !ok {
		return fmt.Errorf("打印文件已失效，请重试")
	}
	if target == "" {
		return fmt.Errorf("未选择保存位置")
	}
	if job.DocPath != "" && samePath(target, job.DocPath) {
		return fmt.Errorf("不能覆盖正在阅读的原文件")
	}
	if !strings.EqualFold(filepath.Ext(target), ".pdf") {
		target += ".pdf"
	}
	dir := filepath.Dir(target)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	src, err := os.Open(job.Path)
	if err != nil {
		return err
	}
	defer src.Close()
	tmp, err := os.CreateTemp(dir, ".pdfviewer-print-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	cleanup := func() {
		tmp.Close()
		os.Remove(tmpName)
	}
	if _, err := io.Copy(tmp, src); err != nil {
		cleanup()
		return err
	}
	if err := tmp.Sync(); err != nil {
		cleanup()
		return err
	}
	if err := tmp.Chmod(0o644); err != nil {
		cleanup()
		return err
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpName)
		return err
	}
	if err := os.Rename(tmpName, target); err != nil {
		// Windows refuses to replace an existing file with Rename.
		if removeErr := os.Remove(target); removeErr == nil {
			err = os.Rename(tmpName, target)
		}
		if err != nil {
			os.Remove(tmpName)
			return err
		}
	}
	s.mu.Lock()
	delete(s.jobs, id)
	s.mu.Unlock()
	removeJobFiles(job)
	return nil
}

// Sweep deletes stale files, including ones no longer tracked in memory.
func (s *Store) Sweep() {
	if s == nil {
		return
	}
	s.mu.Lock()
	now := time.Now()
	for id, job := range s.jobs {
		if now.Sub(job.Created) > sweepAge {
			delete(s.jobs, id)
			_ = os.RemoveAll(filepath.Dir(job.Path))
		}
	}
	s.mu.Unlock()

	entries, err := os.ReadDir(s.dir)
	if err != nil {
		return
	}
	for _, entry := range entries {
		info, err := entry.Info()
		if err != nil {
			continue
		}
		if now.Sub(info.ModTime()) <= sweepAge {
			continue
		}
		if entry.IsDir() {
			_ = os.RemoveAll(filepath.Join(s.dir, entry.Name()))
		} else if strings.HasPrefix(entry.Name(), "print-") {
			_ = os.Remove(filepath.Join(s.dir, entry.Name()))
		}
	}
}

// ClearAll removes every staged print file.
func (s *Store) ClearAll() error {
	if s == nil {
		return nil
	}
	s.mu.Lock()
	jobs := make([]Job, 0, len(s.jobs))
	for _, job := range s.jobs {
		jobs = append(jobs, job)
	}
	s.jobs = make(map[string]Job)
	s.mu.Unlock()
	for _, job := range jobs {
		removeJobFiles(job)
	}
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		_ = os.RemoveAll(filepath.Join(s.dir, entry.Name()))
	}
	return nil
}

func samePath(a, b string) bool {
	aa, errA := filepath.Abs(a)
	bb, errB := filepath.Abs(b)
	if errA != nil || errB != nil {
		return a == b
	}
	return strings.EqualFold(filepath.Clean(aa), filepath.Clean(bb))
}
